Local Ltac lia ::=
  unfold AFS_SIZE, AFS_HDR, AFS_FLAGS in *;
  first [ lazymatch goal with
          | |- aapp _ _ => aapp_win
          | |- _ /\ _ => split; lia
          end
        | first [ lia_goal_ok | lia_exfalso ];
          first [ lia_t1
                | fit_lia_1a
                | progress side_split; lia_t1
                | lia_t2
                | fit_prune_orneg; fit_xlia1
                | fit_prune_orneg; Zify.zify; xlia zchecker
                | lia_t3
                | progress side_split; first [lia_t2 | lia_t3]
                | progress aapp_facts;
                  first [ lia_t1 | progress side_split; lia_t1 | lia_t2 | lia_t3 | progress side_split; first [lia_t2 | lia_t3]
                        | few_placed; progress side_split_all; first [lia_t1 | lia_t3] ]
                | few_placed; progress side_split_all; first [lia_t1 | lia_t3] ] ].
(* [comment removed for export] *)
Ltac fit_slia_atom := first [ exact I | assumption | match goal with K : chunk_disj _ _ _ _ |- _ => exact K end | dj_lia ].
Ltac fit_slia_conj := first [ exact I | lazymatch goal with |- _ /\ _ => split; [fit_slia_atom | fit_slia_conj] end | fit_slia_atom ].
Local Ltac slia ::= fit_slia_conj.
