Definition dof_exit_stmt (pc : Z) : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s5x s6x s7x s8x s9x s11x t3 t4 t5 t6 : word)
    (LF : list fframe) (m mx : mem) (spa : Z) (gsz : nat) (gj : list byte) (cs shc : list cell)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c' : pcore) (pad7 pad2 : list byte) (E' : ecv) (g' : bool)
    (h0 h1 h2 h3 : word) (bflag : byte),
  rw_cells bsegs mx spa cs -> Z.of_nat (cells_size cs) = 216 ->
  rw_cells bsegs mx (spa + 216) [CB gsz gj] ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells bsegs mx ff [C8 h0; C8 h1; C8 h2; C8 h3] -> rw_cells bsegs mx (ff + 504) [C8 (wz fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) shc -> Z.of_nat (cells_size shc) = 64 ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  dof_side H LF m mx lo shi ff fp P E vp (Z.of_nat (length vbs)) ->
  munch (dof_WX H lo sp P E ff fp) m mx -> wmono bsegs m mx ->
  rw_cells bsegs mx P (ParserCoreCells c' pad7 pad2) -> dof_core c c' ->
  rw_cells bsegs mx E (ErrCodeCells E') -> dof_out E' ->
  bytes_at bsegs mx vp vbs -> AHttpCat mx g' ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz (Z.shiftr ff 3 + 2147450880)) (wz ff) s5x s6x s7x s8x s9x (wz ff) s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mx (seg_rom bsegs)).

