Definition dof_exitP_stmt (pc : Z) : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s5x s6x s7x s8x s9x s11x t3 t4 t5 t6 : word)
    (LF : list fframe) (m mx : mem) (spa : Z) (gsz : nat) (gj : list byte) (cs : list cell) (shb : list byte)
    (P E vp fld lo shi ff fp : Z) (vbs : list byte) (c c' : pcore) (pad7 pad2 : list byte) (E' : ecv) (g' : bool)
    (h0 h1 h2 h3 : word) (bflag : byte),
  rw_cells bsegs mx spa cs -> Z.of_nat (cells_size cs) = 216 ->
  rw_cells bsegs mx (spa + 216) [CB gsz gj] ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rw_cells bsegs mx ff [C8 h0; C8 h1; C8 h2; C8 h3] -> rw_cells bsegs mx (ff + 504) [C8 (wz fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 64 shb] ->
  rw_cells bsegs mx fp [C1 bflag] ->
  stk bsegs mx lo spa -> mem_inv bsegs mx ->
  dof_side H LF m mx lo shi ff fp P E vp (Z.of_nat (length vbs)) ->
  munch (dof_WX H lo sp P E ff fp) m mx -> wmono bsegs m mx ->
  rw_cells bsegs mx P (ParserCoreCells c' pad7 pad2) -> dof_core c c' ->
  rw_cells bsegs mx E (ErrCodeCells E') -> dof_out E' ->
  bytes_at bsegs mx vp vbs -> AHttpCat mx g' ->
  dof_bpure sp spa gsz P E lo shi c fld vp vbs -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (dof_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P E lo shi c pad7 pad2 vp vbs m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz (Z.shiftr ff 3 + 2147450880)) (wz ff) s5x s6x s7x s8x s9x (wz ff) s11x t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mx (seg_rom bsegs)).

Local Ltac exitP_script HH STORES :=
  intros ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s5x s6x s7x s8x s9x s11x t3 t4 t5 t6
         LF m mx spa gsz gj cs shb P E vp fld lo shi ff fp vbs c c' pad7 pad2 E' g' h0 h1 h2 h3 bflag;
  intros S1A S1SZ GAP SAV FH FT SHU FL ST MI SD MU WM PC DC EC DOUT WIN HC PURE RA;
destruct PURE as ((PCOK & FLD & LO & CEIL & APP & PAL & APE & EAL & DPE & APV & DVP & DVE & V0 & V47 & SPAL & SHI & V32) & (GAPE & SPA1 & SPA32) & V64);
  destruct (dof_ff_nums _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & N1 & N2 & N3 & N4 & N5 & N6 & N7 & SHFF & NSF & NSP & N32);
  destruct (dof_obj_sep _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (DPF & DEF & DVF & DPP & DEP & DVP1 & DPS & DES & DVS);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APP ltac:(clear; lia)) as (PB1 & PB2 & PB3 & PB4 & _);
  pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (EB1 & EB2 & EB3 & EB4 & _);
  pose proof (aapp_bounds _ _ APV ltac:(clear; lia)) as (VB1 & VB2 & VB3 & VB4 & _);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & AF2 & _);
  unfold AIMG_TOP, AAPP_HI in PB1, PB3, EB1, EB3, VB1, VB3;
  unfold dof_WX, dof_W, DOF_STACK, AASSIGN_STACK, AINTRIN_STACK, AFS_STACK, AFS_FLAGS, AG_HTTP_CAT in *;
  rewrite <- ?SHFF in MU; cbn [app] in MU; unfold wz in *; unfold dof_sav in SAV;
  unfold ErrCodeCells in EC; unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  pose proof (munch_refl [(Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 64)]%Z mx) as MUs;
  pose proof (wmono_refl bsegs mx) as WMs;
  hyde_disj;
  (* [comment removed for export] *)
  STORES;
  lazymatch goal with SHU' : rw_cells _ ?mc (Z.shiftr ff 3 + 2147450880) ?shc' |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (SD' : dof_side H LF m mc lo shi ff fp P E vp (Z.of_nat (length vbs)))
      by (eapply (dof_side_step_sh _ HH); [exact SD| exact MUs| exact WMs| clear; lia| clear; lia| exact SHU'| cbn; clear; lia]);
    assert (HC' : AHttpCat mc g')
      by (eapply AHttpCat_transport; [exact HC| exact MUs| exact WMs| |];
          cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; clear - N6; repeat split; lia);
    clear SD HC MUs WMs;
    pose proof dof_exit as EX; unfold dof_exit_stmt, dof_sav, ADOF_RETIRE, wz in EX;
    eapply (EX ra sp) with (fld := fld); clear EX; try fast_eassumption;
    first [ cbn [cells_size csize Nat.add]; clear; lia
          | unfold dof_WX, dof_W, AFS_FLAGS, AG_HTTP_CAT; cbn [app]; rewrite <- ?SHFF; assumption
          | lazymatch goal with |- dof_bpure _ _ _ _ _ _ _ _ _ _ _ =>
              unfold dof_bpure, dof_pure, dof_lay, DOF_STACK, AASSIGN_STACK, AINTRIN_STACK, AFS_STACK; unhideL;
              repeat match goal with |- _ /\ _ => split end; first [assumption | exact (proj1 FLD) | exact (proj2 FLD)] end
          | lazymatch goal with |- ?G => idtac "EXITP-REM" G end ]
  end.

